import{_ as t,o as r,c as o,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020Q4 Ceph社区季度总结","description":"","frontmatter":{"title":"2020Q4 Ceph社区季度总结","date":"2020-12-01T00:00:00.000Z","tags":["Ceph","社区动态","技术发展"],"outline":"deep"},"headers":[],"relativePath":"quarterly/2020Q4_Ceph社区季度总结.md","filePath":"quarterly/2020Q4_Ceph社区季度总结.md","lastUpdated":1780459816000}'),a={name:"quarterly/2020Q4_Ceph社区季度总结.md"};function i(n,e,s,h,p,g){return r(),o("div",null,[...e[0]||(e[0]=[l('<h2 id="_2020q4-ceph社区季度总结报告" tabindex="-1">2020Q4 Ceph社区季度总结报告 <a class="header-anchor" href="#_2020q4-ceph社区季度总结报告" aria-label="Permalink to &quot;2020Q4 Ceph社区季度总结报告&quot;">​</a></h2><h3 id="_1-主要活动和重点议题" tabindex="-1">1. 主要活动和重点议题 <a class="header-anchor" href="#_1-主要活动和重点议题" aria-label="Permalink to &quot;1. 主要活动和重点议题&quot;">​</a></h3><p>本季度，Ceph社区展开了多项活动和讨论，以下为其中一些重点议题：</p><ul><li><strong>对象上下文锁定恢复问题</strong>：社区针对PG活动集中对象上下文解锁问题进行了深入讨论，并提出了使用<code>with lock</code>原语确保解锁操作被调用的解决方案。</li><li><strong>EIO处理</strong>：讨论了在PG后端处理EIO的适当位置，并决定将EIO处理移至<code>pg.cc</code>。</li><li><strong>性能测试</strong>：社区讨论了将新功能添加到性能测试中，以确保代码路径的持续优化。</li><li><strong>集合树的需求</strong>：针对Ceph存储节点信息创建单独的树的需求展开讨论，并提出了使用现有接口的建议。</li><li><strong>线程池处理</strong>：讨论了线程池处理和心跳计时器的使用，以防止长时间操作导致的心跳问题。</li></ul><h3 id="_2-技术发展和创新亮点" tabindex="-1">2. 技术发展和创新亮点 <a class="header-anchor" href="#_2-技术发展和创新亮点" aria-label="Permalink to &quot;2. 技术发展和创新亮点&quot;">​</a></h3><p>本季度，Ceph社区在技术发展和创新方面取得了以下亮点：</p><ul><li><strong>性能优化</strong>：社区致力于优化Ceph性能，包括EIO处理、线程池处理、缓存分桶代码和MClock调度器测试等方面。</li><li><strong>内存管理</strong>：团队研究了减少碎片化的内存管理策略，以提高系统性能。</li><li><strong>RBD优化</strong>：团队对RBD进行了优化，包括关闭的RBD缓存PR、无缓存重建PR和异步创建镜像快照的性能改进PR等。</li><li><strong>分布式存储系统</strong>：社区讨论了如何适应新的硬件技术（如NVMe over Fabric）和内存技术（如Optane），以及如何改进协议以提高效率。</li></ul><h3 id="_3-重要的决策和里程碑" tabindex="-1">3. 重要的决策和里程碑 <a class="header-anchor" href="#_3-重要的决策和里程碑" aria-label="Permalink to &quot;3. 重要的决策和里程碑&quot;">​</a></h3><p>本季度，Ceph社区在以下方面做出了重要决策：</p><ul><li><strong>EIO处理位置</strong>：决定将EIO处理逻辑移至<code>pg.cc</code>。</li><li><strong>文档编写</strong>：决定编写详细的设计文档来解释EIO处理的设计和实现。</li><li><strong>集合树的需求</strong>：决定不创建单独的树，而是使用现有接口来处理集合信息。</li><li><strong>Messenger更改</strong>：决定进一步研究Messenger在多核环境下的运行问题，并考虑设计变更。</li></ul><h3 id="_4-社区贡献和合作情况" tabindex="-1">4. 社区贡献和合作情况 <a class="header-anchor" href="#_4-社区贡献和合作情况" aria-label="Permalink to &quot;4. 社区贡献和合作情况&quot;">​</a></h3><p>本季度，Ceph社区贡献和合作情况如下：</p><ul><li><strong>性能测试</strong>：社区成员积极参与性能测试，以确保代码路径的持续优化。</li><li><strong>代码审查</strong>：社区成员对多个PR进行审查，以确保代码质量。</li><li><strong>文档编写</strong>：社区成员共同编写和更新文档，以帮助其他用户和开发者。</li></ul><h3 id="_5-下一季度的展望和计划" tabindex="-1">5. 下一季度的展望和计划 <a class="header-anchor" href="#_5-下一季度的展望和计划" aria-label="Permalink to &quot;5. 下一季度的展望和计划&quot;">​</a></h3><p>展望下一季度，Ceph社区计划在以下方面开展工作：</p><ul><li><strong>持续优化性能</strong>：进一步优化EIO处理、线程池处理、缓存分桶代码和MClock调度器测试等方面。</li><li><strong>改进内存管理</strong>：研究更有效的内存管理策略，以提高系统性能。</li><li><strong>代码审查和质量</strong>：继续对PR进行审查，确保代码质量。</li><li><strong>文档编写和维护</strong>：继续编写和更新文档，以帮助其他用户和开发者。</li></ul><p>Ceph社区将继续致力于推动Ceph技术的发展，为用户提供更稳定、高效的分布式存储解决方案。</p>',17)])])}const d=t(a,[["render",i]]);export{c as __pageData,d as default};
